-- Name: stg_nhs_ae_attendances; Type: VIEW; Schema: silver; Owner: -
--

CREATE VIEW silver.stg_nhs_ae_attendances AS
 WITH ranked_records AS (
         SELECT nhs_ae_raw.period_date,
            nhs_ae_raw.org_code,
            nhs_ae_raw.org_name,
            nhs_ae_raw.type1_attendances,
            nhs_ae_raw.type2_attendances,
            nhs_ae_raw.type3_attendances,
            nhs_ae_raw.total_attendances,
            nhs_ae_raw.type1_over4hr,
            nhs_ae_raw.total_over4hr,
            nhs_ae_raw.emergency_admissions,
            nhs_ae_raw.over12hr_trolley_waits,
            nhs_ae_raw.raw_source_file,
            nhs_ae_raw.ingested_at,
            row_number() OVER (PARTITION BY nhs_ae_raw.org_code, nhs_ae_raw.period_date ORDER BY nhs_ae_raw.ingested_at DESC) AS row_num
           FROM bronze.nhs_ae_raw
        )
 SELECT period_date,
    org_code,
    org_name,
    type1_attendances,
    type2_attendances,
    type3_attendances,
    total_attendances,
    type1_over4hr,
    total_over4hr,
    emergency_admissions,
    over12hr_trolley_waits,
        CASE
            WHEN (total_attendances > 0) THEN round(((((total_attendances - total_over4hr))::numeric / (total_attendances)::numeric) * 100.0), 2)
            ELSE 100.00
        END AS performance_4hr_pct,
        CASE
            WHEN (total_attendances > 0) THEN round((((total_over4hr)::numeric / (total_attendances)::numeric) * 100.0), 2)
            ELSE 0.00
        END AS breach_4hr_pct,
    ((org_code)::text = ANY ((ARRAY['REM'::character varying, 'RJR'::character varying, 'RBL'::character varying, 'RWW'::character varying, 'RBS'::character varying, 'REP'::character varying])::text[])) AS is_cheshire_merseyside,
    ((org_code)::text = 'REM'::text) AS is_target_benchmark_trust,
    raw_source_file,
    ingested_at
   FROM ranked_records
  WHERE (row_num = 1);


