CREATE VIEW silver.stg_weather_daily AS
 WITH ranked_records AS (
         SELECT open_meteo_raw.trust_code,
            open_meteo_raw.hospital_name,
            open_meteo_raw.latitude,
            open_meteo_raw.longitude,
            open_meteo_raw.record_date,
            open_meteo_raw.temp_min_c,
            open_meteo_raw.temp_mean_c,
            open_meteo_raw.temp_max_c,
            open_meteo_raw.apparent_temp_min_c,
            open_meteo_raw.wind_speed_max_kmh,
            open_meteo_raw.precipitation_sum_mm,
            open_meteo_raw.is_forecast,
            open_meteo_raw.ingested_at,
            row_number() OVER (PARTITION BY open_meteo_raw.trust_code, open_meteo_raw.hospital_name, open_meteo_raw.record_date ORDER BY open_meteo_raw.ingested_at DESC) AS row_num
           FROM bronze.open_meteo_raw
        )
 SELECT trust_code,
    hospital_name,
    latitude,
    longitude,
    record_date,
    temp_min_c,
    temp_mean_c,
    temp_max_c,
    apparent_temp_min_c,
    wind_speed_max_kmh,
    precipitation_sum_mm,
    round((GREATEST((0.0)::double precision, ((5.0)::double precision - COALESCE(temp_mean_c, (5.0)::double precision))))::numeric, 2) AS cold_snap_degree_days,
        CASE
            WHEN (temp_min_c < (0.0)::double precision) THEN 1
            ELSE 0
        END AS is_frost_day,
    ((trust_code)::text = 'REM'::text) AS is_target_benchmark_trust,
    is_forecast,
    ingested_at
   FROM ranked_records
  WHERE (row_num = 1);


